  constructor(line, message) {
    super(message)
    this.line = line
  }
}

const newTable = () => ({ type: 'table', map: new Map(), headed: false })
const isWs = (c) => c === ' ' || c === '\t'
const isNameChar = (c) => c !== undefined && /^[A-Za-z0-9_-]$/.test(c)

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let current = root
  let currentPath = []
  for (let i = 0; i < lines.length; i++) {
    const p = new LineParser(lines[i], i + 1)
    const r = p.line(root, current, currentPath)
    if (r) {
      current = r.table
      currentPath = r.path
    }
  }
  return root
}

class LineParser {
  constructor(s, n) {
    this.s = s
    this.n = n
    this.i = 0
  }
  fail(msg) {
    throw new ParseError(this.n, msg)
  }
  ws() {
    while (isWs(this.s[this.i])) this.i++
  }
  atEnd() {
    const c = this.s[this.i]
    return c === undefined || c === '#' || c === ';'
  }

  line(root, current, currentPath) {
    this.ws()
    if (this.atEnd()) return null
    if (this.s[this.i] === '[') return this.header(root)
    const names = this.dotted()
    this.ws()
    if (this.s[this.i] !== '=') this.fail('expected key = value')
    this.i++
    const v = this.value(currentPath.concat(names))
    this.assign(current, currentPath, names, v)
    this.ws()
    if (!this.atEnd()) this.fail('trailing text after a value')
    return null
  }

  name() {
    const c = this.s[this.i]
    if (c === '"') return this.basic()
    if (c === "'") return this.literal()
    const st = this.i
    while (isNameChar(this.s[this.i])) this.i++
    if (this.i === st) this.fail('expected a name')
    return this.s.slice(st, this.i)
  }
  dotted() {
    const names = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.s[this.i] === '.') {
        this.i++
        this.ws()
        names.push(this.name())
      } else {
        this.i = save
        return names
      }
    }
  }

  header(root) {
    const aot = this.s[this.i + 1] === '['
    this.i += aot ? 2 : 1
    this.ws()
    const names = this.dotted()
    this.ws()
    const close = aot ? ']]' : ']'
    if (this.s.slice(this.i, this.i + close.length) !== close) this.fail('unterminated table header')
    this.i += close.length
    this.ws()
    if (!this.atEnd()) this.fail('trailing text after a table header')

    let t = root
    const path = []
    for (let k = 0; k < names.length - 1; k++) {
      path.push(names[k])
      t = this.walk(t, names[k], path)
    }
    const last = names[names.length - 1]
    path.push(last)
    const ps = path.join('.')
    const ex = t.map.get(last)
    if (aot) {
      if (!ex) {
        const nt = newTable()
        nt.headed = true
        t.map.set(last, { type: 'array', items: [nt], aot: true })
        return { table: nt, path }
      }
      if (ex.type !== 'array' || !ex.aot) this.fail(`${ps} is not an array of tables`)
      const nt = newTable()
      nt.headed = true
      ex.items.push(nt)
      return { table: nt, path }
    }
    if (!ex) {
      const nt = newTable()
      nt.headed = true
      t.map.set(last, nt)
      return { table: nt, path }
    }
    if (ex.type !== 'table') this.fail(`${ps} is not a table`)
    if (ex.headed) this.fail(`table ${ps} is defined twice`)
    ex.headed = true
    return { table: ex, path }
  }

  // Step through `name` inside table t, creating a table when absent.
  walk(t, name, path) {
    const ex = t.map.get(name)
    if (!ex) {
      const nt = newTable()
      t.map.set(name, nt)
      return nt
    }
    if (ex.type === 'table') return ex
    if (ex.type === 'array' && ex.aot) return ex.items[ex.items.length - 1]
    this.fail(`${path.join('.')} is not a table`)
  }

  assign(t, basePath, names, v) {
    const path = basePath.slice()
    for (let k = 0; k < names.length - 1; k++) {
      path.push(names[k])
      t = this.walk(t, names[k], path)
    }
    path.push(names[names.length - 1])
    const last = names[names.length - 1]
    if (t.map.has(last)) this.fail(`key ${path.join('.')} is defined twice`)
    t.map.set(last, v)
  }

  basic() {
    this.i++
    let out = ''
    for (;;) {
      const c = this.s[this.i]
      if (c === undefined) this.fail('unterminated string')
      this.i++
      if (c === '"') return out
      if (c !== '\\') {
        out += c
        continue
      }
      const e = this.s[this.i]
      if (e === undefined) this.fail('unterminated string')
      this.i++
      const m = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (Object.hasOwn(m, e)) out += m[e]
      else if (e === 'u') {
        const h = this.s.slice(this.i, this.i + 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) this.fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        this.i += 4
      } else {
        const ch = String.fromCodePoint(this.s.codePointAt(this.i - 1))
        this.fail(`invalid escape \\${ch}`)
      }
    }
  }
  literal() {
    const j = this.s.indexOf("'", this.i + 1)
    if (j < 0) this.fail('unterminated string')
    const r = this.s.slice(this.i + 1, j)
    this.i = j + 1
    return r
  }

  value(path) {
    this.ws()
    const c = this.s[this.i]
    if (c === undefined || c === ',' || c === ']' || c === '}' || c === '#' || c === ';') {
      if (!(c === '#' && false)) this.fail('expected a value')
    }
    if (c === '"') return { type: 'string', value: this.basic() }
    if (c === "'") return { type: 'string', value: this.literal() }
    if (c === '[') return this.array(path)
    if (c === '{') return this.inline(path)
    const st = this.i
    while (this.i < this.s.length && !isWs(this.s[this.i]) && !',]};'.includes(this.s[this.i])) this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true' || w === 'false') return { type: 'boolean', value: w === 'true' }
    const D = '[0-9]+(?:_[0-9]+)*'
    if (new RegExp(`^[+-]?${D}$`).test(w)) return { type: 'integer', value: Number(w.replace(/_/g, '')) }
    if (new RegExp(`^[+-]?${D}(?:\\.${D}(?:[eE][+-]?${D})?|[eE][+-]?${D})$`).test(w)) {
      return { type: 'float', value: Number(w.replace(/_/g, '')) }
    }
    this.fail(`invalid value ${w}`)
  }

  array(path) {
    this.i++
    const items = []
    for (;;) {
      this.ws()
      if (this.atEnd()) this.fail('unterminated array')
      if (this.s[this.i] === ']') {
        this.i++
        return { type: 'array', items, aot: false }
      }
      items.push(this.value(path.concat(`[${items.length}]`)))
      this.ws()
      const c = this.s[this.i]
      if (c === ',') this.i++
      else if (c === ']') continue
      else this.fail('unterminated array')
    }
  }

  inline(path) {
    this.i++
    const t = newTable()
    this.ws()
    if (this.atEnd()) this.fail('unterminated inline table')
    if (this.s[this.i] === '}') {
      this.i++
      return t
    }
    for (;;) {
      this.ws()
      if (this.atEnd()) this.fail('unterminated inline table')
      const names = this.dotted()
      this.ws()
      if (this.s[this.i] !== '=') this.fail('expected = in an inline table')
      this.i++
      const v = this.value(path.concat(names))
      this.assign(t, path, names, v)
      this.ws()
      const c = this.s[this.i]
      if (c === ',') this.i++
      else if (c === '}') {
        this.i++
        return t
      } else this.fail('unterminated inline table')
    }
  }
}
